// TestOpenCodeRunPromptEnv_OverridesPWD verifies that the env we hand the
// opencode child process points PWD at the run directory. opencode (Node)
// resolves its project/worktree root from process.env.PWD, and Go's cmd.Dir
// chdirs without updating PWD — so without this override, file operations land
// in the go-test package dir instead of the test repo. See RunPrompt.
func TestOpenCodeRunPromptEnv_OverridesPWD(t *testing.T) {
	t.Setenv("PWD", "/some/stale/go-test/dir")
	t.Setenv("ENTIRE_TEST_TTY", "1")

	dir := t.TempDir()
	env := append(filterEnv(envWith("PWD", "ENTIRE_TEST_TTY"), "ENTIRE_TEST_TTY", "PWD"), "PWD="+dir)

	got, ok := envValue(env, "PWD")
	if !ok {
		t.Fatal("PWD not present in child env")
	}
	if got != dir {
		t.Fatalf("PWD = %q, want %q", got, dir)
	}
	// The stale PWD must not survive (filterEnv strips it before we re-add).
	count := 0
	for _, e := range env {
		if strings.HasPrefix(e, "PWD=") {
			count++
		}
	}
	if count != 1 {
		t.Fatalf("expected exactly one PWD entry, got %d", count)
	}
	if got, ok := envValue(env, "ENTIRE_TEST_TTY"); ok {
		t.Fatalf("ENTIRE_TEST_TTY = %q, want stripped", got)
	}
}

// envWith returns a minimal environment slice containing the given keys with
// their current process values, mimicking the subset of os.Environ() the test
// cares about without depending on the full ambient environment.
func envWith(keys ...string) []string {
	out := make([]string, 0, len(keys))
	for _, k := range keys {
		if v, ok := lookupEnv(k); ok {
			out = append(out, k+"="+v)
		}
	}
	return out
}

